package com.twinlore.app.data.strategywiki

import android.content.Context
import com.twinlore.app.data.canonicalMatchTokens
import com.twinlore.app.data.numberSignature
import dagger.hilt.android.qualifiers.ApplicationContext
import org.json.JSONArray
import javax.inject.Inject
import javax.inject.Singleton

/**
 * In-memory directory of StrategyWiki guides ([MIN_STAGE] and up) loaded once
 * from a bundled JSON asset. Fuzzy-matches a vault game name to the single best
 * [StrategyWikiEntry], or null.
 *
 * The JSON is generated by `StrategyWikiCatalogRegeneratorTest` from saved
 * category-page fixtures.
 */
@Singleton
class StrategyWikiCatalog @Inject constructor(
    @ApplicationContext private val appContext: Context,
) {
    private val entries: List<StrategyWikiEntry> by lazy {
        val json = appContext.assets.open(ASSET_PATH).bufferedReader().use { it.readText() }
        parse(json)
    }

    fun match(gameName: String): StrategyWikiEntry? = bestMatch(entries, gameName)

    companion object {
        const val ASSET_PATH = "strategywiki_catalog.json"
        const val MATCH_THRESHOLD = 0.6

        /**
         * The lowest completion stage the vault will offer a walkthrough from.
         *
         * StrategyWiki's stage 2 ("Maturing") pages are half-written walkthroughs - a couple of
         * early chapters and then nothing - and sending a player to one is worse than offering no
         * guide at all, because the vault presents these as ready-made help rather than as a
         * search result. So only stage 3 ("Thorough") and up stay.
         *
         * Enforced here, in the one place every entry is loaded through, rather than only by
         * leaving them out of the bundled asset - a future regeneration that forgets is then a
         * bigger file, not a stage-2 walkthrough back in front of a player. The asset does leave
         * them out as well (see `StrategyWikiCatalogRegeneratorTest`), so this filter normally has
         * nothing to do.
         */
        const val MIN_STAGE = 3

        /** Test-only factory that bypasses the assets pipeline. */
        fun fromJson(json: String): StrategyWikiCatalogTesting =
            StrategyWikiCatalogTesting(parse(json))

        internal fun parse(json: String): List<StrategyWikiEntry> {
            val arr = JSONArray(json)
            val out = ArrayList<StrategyWikiEntry>(arr.length())
            for (i in 0 until arr.length()) {
                val o = arr.getJSONObject(i)
                val stage = o.getInt("s")
                if (stage < MIN_STAGE) continue
                out += StrategyWikiEntry(
                    title = o.getString("t"),
                    pagePath = o.getString("a"),
                    stage = stage,
                )
            }
            return out
        }

        internal fun bestMatch(entries: List<StrategyWikiEntry>, gameName: String): StrategyWikiEntry? {
            if (gameName.isBlank()) return null
            // Canonical tokens (region tags stripped, Roman→Arabic) shared with
            // VgmapsCatalog — see com.twinlore.app.data.NameNumerals.
            val inputTokenList = canonicalMatchTokens(gameName)
            val inputTokens = inputTokenList.toSet()
            if (inputTokens.isEmpty()) return null
            val inputNumbers = numberSignature(inputTokenList)
            val normInput = inputTokenList.joinToString(" ")

            data class Scored(
                val entry: StrategyWikiEntry,
                val score: Double,
                val isExact: Boolean,
                val isPrefix: Boolean,
                val titleLen: Int,
            )

            val scored = entries.mapNotNull { e ->
                val titleTokenList = canonicalMatchTokens(e.title)
                val titleTokens = titleTokenList.toSet()
                // Sequel guard: the set of numbers must match exactly, so a
                // base game never matches a numbered sequel and "2" never
                // matches "3" (Roman/Arabic already unified by canonTokens).
                if (numberSignature(titleTokenList) != inputNumbers) return@mapNotNull null
                val union = inputTokens.union(titleTokens).size
                if (union == 0) return@mapNotNull null
                val score = inputTokens.intersect(titleTokens).size.toDouble() / union
                if (score < MATCH_THRESHOLD) return@mapNotNull null
                val normTitle = titleTokenList.joinToString(" ")
                Scored(e, score, normTitle == normInput, normTitle.startsWith(normInput), normTitle.length)
            }

            return scored
                .sortedWith(
                    compareByDescending<Scored> { it.isExact }
                        .thenByDescending { it.score }
                        .thenByDescending { it.isPrefix }
                        .thenByDescending { it.entry.stage }
                        .thenBy { it.titleLen }
                        .thenBy { it.entry.title }
                )
                .firstOrNull()
                ?.entry
        }
    }
}

/**
 * Test-only wrapper exposing the matcher without an Android Context.
 * Kept in this file so it can call the internal bestMatch helper.
 */
class StrategyWikiCatalogTesting internal constructor(private val entries: List<StrategyWikiEntry>) {
    fun match(gameName: String): StrategyWikiEntry? = StrategyWikiCatalog.bestMatch(entries, gameName)
}
